// Pull the parts of a VAPI end-of-call-report we actually store.
//
// VAPI posts several message types to the same URL - status-update,
// speech-update, hang, end-of-call-report. Only the last one carries the
// transcript and the recording, so everything else is acknowledged and dropped.
// Answering 200 to those matters: VAPI retries anything that is not a 2xx.
const b = ($input.first().json || {}).body || {};
const m = b.message || b;

if (m.type !== 'end-of-call-report') {
  return [{ json: { skip: true, reason: 'message type ' + (m.type || 'unknown') + ' - nothing to log' } }];
}

const e164 = (v) => {
  const d = String(v || '').replace(/[^\d+]/g, '');
  if (/^\+\d{10,15}$/.test(d)) return d;
  if (/^1\d{10}$/.test(d)) return '+' + d;
  if (/^\d{10}$/.test(d)) return '+1' + d;
  return null;
};

const call = m.call || {};
// The number the agent ANSWERED on identifies the client. The number that rang
// it is the lead. VAPI has moved these between the envelope and the call object
// across versions, so read both rather than pinning one.
const answered = e164((m.phoneNumber || call.phoneNumber || {}).number);
const caller = e164((m.customer || call.customer || {}).number);

if (!answered) {
  return [{ json: { skip: true, reason: 'no answering number in the report - cannot tell which client this call belongs to' } }];
}

const artifact = m.artifact || {};
const analysis = m.analysis || {};
const data = analysis.structuredData || {};

// Turn-by-turn, minus the system prompt - that is Sanaku's, not the client's,
// and it would be sitting in their portal for anyone at the company to read.
const turns = (artifact.messages || [])
  .filter((t) => t.role !== 'system')
  .map((t) => ({ role: t.role, message: t.message, at: t.secondsFromStart }));

let seconds = Number(m.durationSeconds);
if (!Number.isFinite(seconds) && m.startedAt && m.endedAt) {
  seconds = (new Date(m.endedAt) - new Date(m.startedAt)) / 1000;
}

return [{ json: {
  skip: false,
  call_id: call.id || m.callId || null,
  answered,
  caller,
  ended_reason: m.endedReason || null,
  recording_url: artifact.recordingUrl || artifact.stereoRecordingUrl || null,
  transcript: turns,
  transcript_text: artifact.transcript || null,
  summary: analysis.summary || null,
  duration_seconds: Number.isFinite(seconds) ? Math.round(seconds) : null,
  data,
} }];

// Score the call from what the agent extracted, and work out whether it
// landed outside the client's own opening hours.
const client = $('Client Active? (kill switch)').first().json;
const call = $('Normalize Call').first().json;

// Already Logged? runs with alwaysOutputData, so an empty result still arrives
// as one item - an id is the only proof a row exists.
const already = ($input.all() || []).some((i) => i.json && i.json.id);

// after_hours against the CLIENT's hours, same rule T1 uses, so the two
// channels count the same thing on the same statement.
const tz = client.timezone || 'America/Los_Angeles';
const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: tz, hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit',
}).formatToParts(new Date());
const get = (t) => parts.find((p) => p.type === t).value;
const hour = Number(get('hour'));
const minute = Number(get('minute'));
const dow = get('weekday').toLowerCase();

const span = (client.business_hours || {})[dow];
let afterHours = true;
if (Array.isArray(span) && span.length === 2) {
  const mins = hour * 60 + minute;
  const toMin = (s) => Number(String(s).split(':')[0]) * 60 + Number(String(s).split(':')[1] || 0);
  afterHours = !(mins >= toMin(span[0]) && mins < toMin(span[1]));
}

const d = call.data || {};
const urgency = String(d.urgency || '').toLowerCase();
const name = d.caller_name || null;
const job = d.job_type || null;

// The agent hears a callback number spoken and writes it down as it was said -
// "seven one four, five five five...". Store E.164 like every other channel,
// or the reply handler cannot match this lead to an inbound text later.
const e164 = (v) => {
  const digits = String(v || '').replace(/[^\d+]/g, '');
  if (/^\+\d{10,15}$/.test(digits)) return digits;
  if (/^1\d{10}$/.test(digits)) return '+' + digits;
  if (/^\d{10}$/.test(digits)) return '+1' + digits;
  return null;
};
const phone = e164(d.callback_number) || call.caller || null;

// A lead is worth waking someone for when the agent got a job and a way to
// call back. Wrong numbers and price-shoppers score low and stay silent.
let score = 0;
if (job) score += 35;
if (phone) score += 25;
if (name) score += 10;
if (urgency === 'emergency') score += 30;
else if (urgency === 'soon') score += 15;
if (d.address) score += 10;
score = Math.min(100, score);

// The agent's own verdict wins when it gave one - it heard the call.
const qualified = typeof d.is_qualified === 'boolean' ? d.is_qualified : score >= 60;

// Only claim a booking when the agent actually made one. A qualified caller who
// hung up before a time was agreed is not booked, and the portal saying so
// would be the client's first reason to stop believing the numbers.
const outcome = d.appointment_booked === true ? 'booked' : null;

return [{ json: {
  already,
  client_id: client.id,
  brand: client.brand_name || client.company_name,
  from_number: client.sending_number || client.inbound_number,
  escalation_phone: client.escalation_phone,
  name, phone, job, urgency,
  address: d.address || null,
  preferred_time: d.preferred_time || null,
  after_hours: afterHours,
  qualified,
  outcome,
  score,
  call_id: call.call_id,
  recording_url: call.recording_url,
  transcript: call.transcript,
  summary: call.summary || call.transcript_text,
  duration_seconds: call.duration_seconds,
  ended_reason: call.ended_reason,
} }];

// One text to the owner, in their own voice, with enough to act on.
// Nothing here names Sanaku.
const g = $('Grade Call').first().json;
const row = $input.first().json;

const mins = g.duration_seconds == null ? null : Math.floor(g.duration_seconds / 60);
const secs = g.duration_seconds == null ? null : g.duration_seconds % 60;
const length = mins == null ? '' : ' (' + mins + 'm ' + String(secs).padStart(2, '0') + 's)';

const lines = [];
lines.push(g.outcome === 'booked' ? 'Job booked from a call' + length
  : g.qualified ? 'New call answered' + length
  : 'Call answered, low priority' + length);
if (g.name) lines.push('Who: ' + g.name);
if (g.phone) lines.push('Call back: ' + g.phone);
if (g.job) lines.push('Job: ' + g.job);
if (g.address) lines.push('Where: ' + g.address);
if (g.urgency) lines.push('Urgency: ' + g.urgency);
if (g.preferred_time) lines.push('Wants: ' + g.preferred_time);
if (g.summary) lines.push('', String(g.summary).slice(0, 300));

// Only wake them outside opening hours if it is actually worth waking for.
const worth = g.qualified || g.urgency === 'emergency';
const send = !!g.escalation_phone && (worth || !g.after_hours);

return [{ json: {
  send,
  to: g.escalation_phone,
  from: g.from_number,
  body: lines.join('\n'),
  lead_id: (row && row.id) || null,
} }];
